python3 -c "
import yaml, glob, os

# Find all module.yml files
results = []
for root, dirs, files in os.walk('/root/zephyrproject/modules'):
    for f in files:
        if f == 'module.yml':
            path = os.path.join(root, f)
            if '/zephyr/' in path:
                results.append(path)

# Known schema keys
known_top_keys = {'name', 'build', 'tests', 'samples', 'boards', 'blobs', 'security', 'package-managers'}
known_blob_keys = {'path', 'sha256', 'type', 'version', 'license-path', 'url', 'description', 'doc-url'}

for path in results:
    with open(path) as f:
        try:
            data = yaml.safe_load(f)
        except:
            continue
    if not isinstance(data, dict):
        continue

    # Check top-level keys
    extra_top = set(data.keys()) - known_top_keys
    if extra_top:
        print(f'{path}: extra top-level keys: {extra_top}')

    # Check blob keys
    if 'blobs' in data and isinstance(data['blobs'], list):
        for i, blob in enumerate(data['blobs']):
            if isinstance(blob, dict):
                extra_blob = set(blob.keys()) - known_blob_keys
                if extra_blob:
                    print(f'{path}: blob[{i}] extra keys: {extra_blob}')
"
